// TH16 v1.00a Stage 6 BossCard9 (SUBSEASON=3) "「裏・エクストリームウィンター」"
// Source: st06bs.ecl.txt:2586-2683 entry, dependencies 2685-2940.
// Source frames count from the entry timerReset(2603); the spell() at 2623 opens the
// 7200-frame interrupt window.  This card keeps that window through phase_begin.

const TIME_LIMIT: int = 7324;      // 120 shell buffer + 7200 source window + 4 startup
const OPENING_BUFFER: int = 120;

// TH16 bullet types (approved aliases of the identical TH18 0-43 slots, source=th16).
const TH16_GLOW_BALL: int = 880;   // source type 33
const TH16_DROPLET: int = 896;     // source type 34

// Phase generation for the tasks the source cancels with killAsync(2/3/4).
const GVAR_GEN: int = 0;

// ---- source BossCard9_at2 (2700-2754): fixed ring, base rotates +1.941611 rad/wave ----
async sub boss_at2(gen: int) {
    var n: int = 8;                 // count: E3 N8 H8 L(LO)8
    var speed: fx = 2.6fx;          // speed: E2.2 N2.2 H2.4 L(LO)2.6
    var gap: int = 7;               // wait:  E20 N10 H8 L(LO)7
    if global(GVAR_RANK) == RANK_EASY { n = 3; speed = 2.2fx; gap = 20; }
    var base: int = 16384;          // %B = 1.570796f
    loop {
        if self_int(GVAR_GEN) != gen { return; }
        ring_mode5(TH16_DROPLET, 6, n, base, speed);
        base = base + 20252;        // %B += 1.941611
        if base >= 65536 { base = base - 65536; }
        wait(gap);
    }
}

// ---- source BossCard9_at3 (2756-2807): fixed ring, base rotates -3.883222 rad/wave ----
async sub boss_at3(gen: int) {
    var n: int = 32;                // count: E15 N32 H32 L(LO)32
    var speed: fx = 2.0fx;          // speed: E1.5 N1.5 H1.5 L(LO)2.0
    var gap: int = 16;              // wait:  E40 N20 H16 L(LO)16
    if global(GVAR_RANK) == RANK_EASY { n = 15; speed = 1.5fx; gap = 40; }
    var base: int = 16384;          // %B = 1.570796f
    loop {
        if self_int(GVAR_GEN) != gen { return; }
        ring_mode5(TH16_DROPLET, 6, n, base, speed);
        base = base - 40503;        // %B -= 3.883222
        if base < 0 { base = base + 65536; }
        wait(gap);
    }
}

// ---- source BossCard9_at4 (2809-2840): fixed ring, random base angle each wave ----
async sub boss_at4(gen: int) {
    var n: int = 12;                // count: E4 N8 H10 L(LO)12
    var speed: fx = 1.5fx;          // etSpeed(1.5f, 0.2f), one layer
    if global(GVAR_RANK) == RANK_EASY { n = 4; }
    loop {
        if self_int(GVAR_GEN) != gen { return; }
        ring_mode5(TH16_GLOW_BALL, 3, n, rand(65536), speed);   // %RANDRAD
        wait(60);
    }
}

// ---- source BossCard9_at (2685-2698): emitter tasks + boss ellipse sweep ----
async sub boss_at() {
    wait(60);
    spawn boss_at_f();              // 2688 @BossCard9_at_f(12, 2, 3.883222) async
    spawn boss_at_f3();             // 2689 @BossCard9_at_f3() async
    // 2690 moveEllipse(1.5707964, 0.0052359877, 0, 0, 1.5707964, 0.1)
    // 2691 moveEllipseTime(120, -999999, -999999, 128, 0, 1.5707964, 0.1)
    // center C fixed at the position when set = (0,128); axis beta = pi/2, ratio 0.1;
    // phase starts at pi/2, omega = pi/600 rad/frame = 65536/1200 BAM/frame; radius
    // ramps 0 -> 128 over 120 motion ticks.  Ellipse: x = Cx - r*sin(t),
    // y = Cy + 0.1*r*cos(t) with t = theta - beta.
    var k: int = 0;
    loop {
        var r: fx = 128fx;
        if k < 120 { r = ((k * 128) as fx) / 120; }
        var delta: int = ((k * 65536) / 1200) % 65536;
        var d: angle = delta as angle;
        var u: fx = (r * 0.1fx) * cos(d);
        move_to(0, 0fx - r * sin(d), 128fx + u, EASE_LINEAR);
        k = k + 1;
        wait(1);
    }
}

// ---- source BossCard9_at_f (2842-2876) and at_f2 (2878-2894): 4 Infinite lasers ----
// laserNew(0, 512, 512, 0, 16) + laserTiming(0, 40, 20, 200, 20, 0):
// Infinite judge segment start 0, length 0.9*512 = 460.8; judge width w=16 -> 8.
// State 4 (expand) and 2 (hold) collide; shrink does not -> warn 40, active 220, fade 20.
// Constant width through expand is the accepted laser_approx (meta laser_approx=true).
// at_f2 re-writing the offsets from FINAL_X+-64/FINAL_Y every frame is lz_anchor here.
async sub boss_at_f() {
    loop {
        var l1: int = laser(6, $self_x + 64fx, $self_y, 90deg, 460.8fx, 8fx, 40, 220, 20);
        lz_anchor(l1, $self_enemy, 64fx, 0fx);
        var l2: int = laser(6, $self_x - 64fx, $self_y, 90deg, 460.8fx, 8fx, 40, 220, 20);
        lz_anchor(l2, $self_enemy, -64fx, 0fx);
        var l3: int = laser(6, $self_x - 64fx, $self_y, 18432bam, 460.8fx, 8fx, 40, 220, 20);
        lz_anchor(l3, $self_enemy, -64fx, 0fx);
        var l4: int = laser(6, $self_x + 64fx, $self_y, 14336bam, 460.8fx, 8fx, 40, 220, 20);
        lz_anchor(l4, $self_enemy, 64fx, 0fx);
        wait(400);
    }
}

// ---- source BossCard9_at_f3 (2896-2940): 60-frame warmup, fixed ring, rotating base ----
async sub boss_at_f3() {
    wait(60);
    var n: int = 80;                // count: E32 N64 H70 L(LO)80
    var speed: fx = 3.1fx;          // speed: E2.5 N2.5 H2.8 L(LO)3.1
    if global(GVAR_RANK) == RANK_EASY { n = 32; speed = 2.5fx; }
    var base: int = rand(65536);    // %B = %RANDRAD
    loop {
        ring_mode5(TH16_DROPLET, 8, n, base, speed);
        base = base + 40503;        // %B += 3.883222
        if base >= 65536 { base = base - 65536; }
        wait(60);
    }
}

// aim mode 5: angle = alpha + pi/N + 2*pi*i/N + q*delta, one layer (q=0).
// etEx(id, 0, 2, 1, ...) is ANIM a=1: spawning position is displaced by -4*velocity.
sub ring_mode5(shape: int, color: int, n: int, base: int, speed: fx) {
    var d: fx = speed * 4fx;
    for i in 0..n {
        var a: int = (base + 32768 / n + (i * 65536) / n) % 65536;
        var ang: angle = a as angle;
        _ = fire(shape, color, $self_x - d * cos(ang), $self_y - d * sin(ang),
                 speed, ang, none, none);
    }
}

// ---- source BossCard9 (2586-2683) ----
async sub boss_card9() {
    set_invuln(65535);
    set_hurtbox(28fx);              // Boss() setHurtbox(56,56): circle radius 28
    set_hitbox(25fx);               // Boss() setHitbox(50,50): circle radius 25
    // 2589-2593: $TIMEOUT==0 on entry -> etClear(640)
    clear_bullets_at($self_x, $self_y, 640fx, 0);
    // 2595 lifeSet(5300) is the spawn hp; 2596-2602 anm/stars/sound are presentation.
    // 2603 timerReset(): the source TIME fallbacks below start counting here.
    // 2604-2615 killAllAsync/enmKillAll/spellEnd/funcSet(0)/laserCancel: no leftovers.
    // 2616-2618 moveVel/moveVelTime/movePosTime resets: boss enters at rest.
    // 2622 setInterrupt(0,0,7200,"BossDead") and 2623 spell(102,7200,0,...) are the
    //   phase time limit (see TIME_LIMIT / phase_begin).
    // 2624-2626 lifeMarker: HP-bar UI omitted.  2627-2632 anm/sound omitted.
    // 2628 movePosTime(60,4,0,128): zero displacement, the boss already sits at (0,128).
    var t: int = 0;
    for i in 0..90 { wait(1); t = t + 1; }          // 2633 +90 time gate
    // 2635 moveLimit(0,160,320,320) -> x[-160,160] y[0,320]; the sweep stays inside
    //   x[-128,128] y[115.2,140.8], so the clamp never acts.
    // 2636 funcSet(2) and 2637 bombInvuln(0): no-DPS invulnerable shell (approved).
    spawn boss_at();                                // 2638 @BossCard9_at() async 1
    // 2643/2651/2661: LIFE gates never fall without DPS; TIME gates close at 1801/3601/5401.
    while $self_hp > 3700 && t <= 1800 { wait(1); t = t + 1; }
    clear_bullets_at($self_x, $self_y, 640fx, 0);   // 2645 etClear(640)
    set_self_int(GVAR_GEN, 1);                      // phase generation for the at2 task
    spawn boss_at2(1);                              // 2646
    while $self_hp > 2600 && t <= 3600 { wait(1); t = t + 1; }
    clear_bullets_at($self_x, $self_y, 640fx, 0);   // 2653
    set_self_int(GVAR_GEN, 2);
    spawn boss_at2(2);                              // 2655 (killAsync(2) at 2654)
    spawn boss_at3(2);                              // 2656
    while $self_hp > 1500 && t <= 5400 { wait(1); t = t + 1; }
    clear_bullets_at($self_x, $self_y, 640fx, 0);   // 2663
    set_self_int(GVAR_GEN, 3);
    spawn boss_at2(3);                              // 2667 (killAsync 2/3/4 at 2664-2666)
    spawn boss_at3(3);                              // 2668
    spawn boss_at4(3);                              // 2669
    // 2670-2681: %F0 = 1.0f (never read by this card) and $A = 10000 counted down by a
    // 330-frame idle loop.  $A cannot run out inside the 7200-frame window, so the loop
    // only idles until the setInterrupt(0,0,7200,"BossDead") interrupt ends the card.
    while t < 7200 { wait(1); t = t + 1; }
    // BossDead interrupt: the attack ends, the real enemy leaves the field.
}

// ---- training shell (validation.md) ----
async sub boss_pattern() {
    wait(OPENING_BUFFER);
    _ = spawn_enemy(0fx, 128fx, 5300, 0, 0, 0, boss_card9);
}

async sub control() {
    set_invuln(65535);
    set_enemy_flag(ENEMY_NO_BODY, 1);
    phase_begin(0, boss_pattern, TIME_LIMIT, 0);
    wait_spell();
    loop { wait(1); }
}

sub main() {
    _ = spawn_enemy(0fx, 0fx, 1000, 0, 0, 0, control);
    loop { wait(600); }
}
